from collections import deque,Counter

def rightmost_shadow_components(grid, bg=None, conn8=True):
 if bg is None: bg=Counter(v for row in grid for v in row).most_common(1)[0][0]
 h,w=len(grid),len(grid[0]); seen=set(); out=[r[:] for r in grid]
 neigh=[(dr,dc) for dr in (-1,0,1) for dc in (-1,0,1) if (dr or dc) and (conn8 or abs(dr)+abs(dc)==1)]
 for r in range(h):
  for c in range(w):
   if grid[r][c]==bg or (r,c) in seen: continue
   q=[(r,c)]; seen.add((r,c)); comp=[]
   while q:
    y,x=q.pop(); comp.append((y,x))
    for dy,dx in neigh:
     yy,xx=y+dy,x+dx
     if 0<=yy<h and 0<=xx<w and grid[yy][xx]!=bg and (yy,xx) not in seen:
      seen.add((yy,xx));q.append((yy,xx))
   mx=max(x for y,x in comp)
   for y in set(y for y,x in comp if x==mx):
    rowmax=max(x for yy,x in comp if yy==y)
    for x in range(rowmax+1,w):
     if out[y][x]==bg: out[y][x]=1
 return out
