def band_rightmost(grid):
 bg=Counter(v for row in grid for v in row).most_common(1)[0][0];h=len(grid);w=len(grid[0]);out=[r[:] for r in grid]
 bands=[];r=0
 while r<h:
  while r<h and all(v==bg for v in grid[r]):r+=1
  if r>=h:break
  a=r
  while r<h and not all(v==bg for v in grid[r]):r+=1
  bands.append((a,r))
 for a,b in bands:
  mx=max(c for y in range(a,b) for c,v in enumerate(grid[y]) if v!=bg)
  for y in range(a,b):
   if any(grid[y][c]!=bg for c in range(mx+1)) and grid[y][mx]!=bg:
    # only rows whose rightmost foreground reaches band max
    if max(c for c,v in enumerate(grid[y]) if v!=bg)==mx:
     for x in range(mx+1,w):out[y][x]=1
 return out
