heurcode='''from collections import Counter

def transform(grid):
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    r = 0
    while r < h:
        while r < h and all(v == bg for v in grid[r]):
            r += 1
        if r == h:
            break
        start = r
        while r < h and not all(v == bg for v in grid[r]):
            r += 1
        end = r
        for y in range(start, end):
            right = max((x for x,v in enumerate(grid[y]) if v != bg), default=-1)
            if right < 0 or right == w-1:
                continue
            # A trailing region clear in both vertical neighbors gets a full shadow.
            clear = all((y == 0 or grid[y-1][x] == bg) and
                        (y == h-1 or grid[y+1][x] == bg)
                        for x in range(right+1, w))
            # Do not shadow a leading singleton tip in a multirow band.
            leading_singleton = (y == start and end-start > 1 and
                                 grid[y][right] != bg and
                                 (right == 0 or grid[y][right-1] == bg))
            if clear and not leading_singleton:
                for x in range(right+1, w):
                    out[y][x] = 1
            elif y == end-1 and right+1 < w and y > 0 and grid[y-1][right+1] != bg:
                # An exposed lower edge under a one-cell overhang leaves an alternating shadow.
                for x in range(right+2, w, 2):
                    out[y][x] = 1
    return out
'''
